<script setup lang="ts">
import {money} from '~/shared/types'
const api=useApi(),route=useRoute(),router=useRouter(),search=ref(String(route.query.q||''))
const query=computed(()=>({q:String(route.query.q||''),status:String(route.query.status||''),page:Number(route.query.page)||1,pageSize:10}))
const {data,pending,error,refresh}=await useAsyncData(()=>`admin-products-${JSON.stringify(query.value)}`,()=>api.adminProducts(query.value),{watch:[query]})
const {data:categories}=await useAsyncData('categories',()=>api.categories())
const statuses:Record<string,string>={draft:'Черновик',published:'Опубликован',archived:'В архиве'}
function update(values:Record<string,string|number|undefined>){router.push({query:{...route.query,page:undefined,...values}})}
useSeoMeta({title:'Товары — демо-панель Deadlock Family'})
</script>
<template><AdminShell title="Товары"><div class="admin-toolbar"><form class="search-field" @submit.prevent="update({q:search||undefined})"><AppIcon name="search" :size="19"/><input v-model="search" aria-label="Найти товар в админ-панели" placeholder="Найти товар…"><button aria-label="Поиск"><AppIcon name="arrow" :size="18"/></button></form><select class="filter-select" aria-label="Статус публикации" :value="query.status" @change="update({status:($event.target as HTMLSelectElement).value||undefined})"><option value="">Все статусы</option><option value="draft">Черновики</option><option value="published">Опубликованные</option><option value="archived">В архиве</option></select><NuxtLink to="/admin/products/new" class="btn btn-primary"><AppIcon name="plus" :size="17"/>Создать товар</NuxtLink></div><ApiState :pending="pending" :error="error" :empty="!data?.items.length" @retry="refresh()"/><div v-if="data?.items.length&&!pending&&!error" class="table-wrap"><table class="admin-table"><thead><tr><th>Товар</th><th>Категория</th><th>Цена</th><th>Статус</th><th>Варианты / остаток</th><th>Обновлён</th><th/></tr></thead><tbody><tr v-for="p in data.items" :key="p.id"><td><NuxtLink :to="`/admin/products/${p.id}`" class="table-product"><img v-if="p.images[0]" :src="p.images[0].url" :alt="p.name" width="48" height="44"><span>{{p.name}}</span></NuxtLink></td><td>{{categories?.find(c=>c.slug===p.category)?.name}}</td><td>{{money(p.price)}}</td><td><span class="status-pill">{{statuses[p.status]}}</span></td><td>{{p.variants.length}} / {{p.variants.reduce((n,v)=>n+v.stock,0)}} шт.</td><td>{{new Date(p.updatedAt).toLocaleDateString('ru-RU')}}</td><td><NuxtLink :to="`/admin/products/${p.id}`" class="text-link">Изменить</NuxtLink></td></tr></tbody></table></div><div v-if="data&&data.total>data.pageSize" class="pagination"><button class="btn btn-small" :disabled="data.page<=1" @click="update({page:data.page-1})">Назад</button><span>{{data.page}} / {{Math.ceil(data.total/data.pageSize)}}</span><button class="btn btn-small" :disabled="data.page*data.pageSize>=data.total" @click="update({page:data.page+1})">Далее</button></div></AdminShell></template>
